            segs.push_back({a, N});
            segs.push_back({0, b});
        }
    }

    if (segs.empty()) {
        return 0;
    }

    sort(segs.begin(), segs.end());

    vector<pair<long long, long long>> merged;
    for (auto &s : segs) {
        if (merged.empty() || merged.back().second < s.first) {
            merged.push_back(s);
        } else {
            merged.back().second = max(merged.back().second, s.second);
        }
    }

    // Since the wall is circular, first and last intervals may connect through 0/N.
    if (merged.size() >= 2 && merged.front().first == 0 && merged.back().second == N) {
        merged.front().first = merged.back().first;
        merged.front().second = merged.front().second; // unchanged
