typedef long long ll;

typedef struct {
    ll l, r; /* interval [l, r) */
} Interval;

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int cmp_interval(const void *a, const void *b) {
    const Interval *x = (const Interval *)a;
    const Interval *y = (const Interval *)b;
    if (x->l < y->l) return -1;
    if (x->l > y->l) return 1;
    if (x->r < y->r) return -1;
    if (x->r > y->r) return 1;
    return 0;
}

typedef struct {
    ll len;
    ll cnt;
} Pair;

int cmp_pair_desc(const void *a, const void *b) {
    const Pair *x = (const Pair *)a;
    const Pair *y = (const Pair *)b;
    if (x->len > y->len) return -1;
    if (x->len < y->len) return 1;
    return 0;
}

int main(void) {
    ll N, M;
    if (scanf("%lld %lld", &N, &M) != 2) return 0;

    if (M == 0) return 0;

    /* At most 2 intervals per child after unrolling circle */
    Interval *arr = (Interval *)malloc(sizeof(Interval) * (2 * M + 5));
    ll k = 0;

    for (ll i = 0; i < M; ++i) {
        ll a, L;
        scanf("%lld %lld", &a, &L);

        if (N == 0) continue;

        if (L >= N) {
            /* whole circle painted */
            arr[k].l = 0;
            arr[k].r = N;
            k++;
            continue;
        }

        ll end = (a + L) % N;
        if (a + L < N) {
            arr[k].l = a;
            arr[k].r = a + L;
            k++;
        } else {
            arr[k].l = a;
            arr[k].r = N;
            k++;
            arr[k].l = 0;
            arr[k].r = end;
            k++;
        }
    }

    if (k == 0) return 0;

    qsort(arr, k, sizeof(Interval), cmp_interval);

    /* Merge intervals on [0, N) */
    Interval *merged = (Interval *)malloc(sizeof(Interval) * (k + 5));
    ll mk = 0;

    ll curL = arr[0].l, curR = arr[0].r;
    for (ll i = 1; i < k; ++i) {
        if (arr[i].l <= curR) {
            if (arr[i].r > curR) curR = arr[i].r;
        } else {
            merged[mk].l = curL;
            merged[mk].r = curR;
            mk++;
            curL = arr[i].l;
            curR = arr[i].r;
        }
    }
    merged[mk].l = curL;
    merged[mk].r = curR;
    mk++;

    /* Because wall is circular, first and last may connect through 0/N */
    if (mk >= 2 && merged[0].l == 0 && merged[mk - 1].r == N) {
        merged[mk - 1].r = merged[0].r + N;
        for (ll i = 0; i + 1 < mk; ++i) merged[i] = merged[i + 1];
        mk--;
    }

    ll *lengths = (ll *)malloc(sizeof(ll) * (mk + 5));
    for (ll i = 0; i < mk; ++i) lengths[i] = merged[i].r - merged[i].l;

    qsort(lengths, mk, sizeof(ll), cmp_ll);

    Pair *ans = (Pair *)malloc(sizeof(Pair) * (mk + 5));
    ll ak = 0;

    for (ll i = mk - 1; i >= 0; ) {
        ll j = i;
        while (j >= 0 && lengths[j] == lengths[i]) j--;
        ans[ak].len = lengths[i];
        ans[ak].cnt = i - j;
        ak++;
        i = j;
    }

    for (ll i = 0; i < ak; ++i) {
        printf("%lld %lld\n", ans[i].len, ans[i].cnt);
    }

    free(arr);
    free(merged);
    free(lengths);
    free(ans);
    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int N = Integer.parseInt(firstLine[0]);
        int M = Integer.parseInt(firstLine[1]);

        // Use TreeSet to store intervals sorted by start
        TreeSet<int[]> intervals = new TreeSet<>((a, b) -> Integer.compare(a[0], b[0]));

        for (int i = 0; i < M; i++) {
            String[] line = br.readLine().split(" ");
            int a = Integer.parseInt(line[0]);
            int L = Integer.parseInt(line[1]);
            int end = (a + L) % N;

            // Add interval, handling wrap-around
            if (a + L >= N) {
                // Wraps around
                addInterval(intervals, a, N - 1);
                addInterval(intervals, 0, end);
            } else {
                addInterval(intervals, a, end - 1);
            }
        }

        // If there are no intervals, output nothing
        if (intervals.isEmpty()) {
            return;
        }

        // Merge intervals and collect lengths
        List<Integer> lengths = new ArrayList<>();
        int[] prev = null;
        for (int[] cur : intervals) {
            if (prev == null) {
                prev = new int[]{cur[0], cur[1]};
            } else {
                if (cur[0] <= prev[1] + 1) {
                    // Overlapping or adjacent, merge
                    prev[1] = Math.max(prev[1], cur[1]);
                } else {
                    lengths.add(prev[1] - prev[0] + 1);
                    prev = new int[]{cur[0], cur[1]};
                }
            }
        }
        if (prev != null) {
            lengths.add(prev[1] - prev[0] + 1);
        }

        // Check if the merged intervals wrap around (first and last may connect)
        if (lengths.size() > 1) {
            // Get first and last interval from the sorted set
            int[] firstInterval = intervals.first();
            int[] lastInterval = intervals.last();
            // If last interval ends at N-1 and first starts at 0, they are adjacent on the circle
            if (lastInterval[1] == N - 1 && firstInterval[0] == 0) {
                // Merge first and last lengths
                int mergedLen = lengths.get(lengths.size() - 1) + lengths.get(0);
                lengths.set(0, mergedLen);
                lengths.remove(lengths.size() - 1);
            }
        }

        // Count frequencies
        Map<Integer, Integer> freq = new TreeMap<>(Collections.reverseOrder());
        for (int len : lengths) {
            freq.put(len, freq.getOrDefault(len, 0) + 1);
        }

        // Output
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            sb.append(entry.getKey()).append(" ").append(entry.getValue()).append("\n");
        }
        System.out.print(sb);
    }

    private static void addInterval(TreeSet<int[]> intervals, int start, int end) {
        if (start > end) return;
        int[] newInterval = new int[]{start, end};
        // Find intervals that overlap or are adjacent
        Integer floorKey = intervals.floorKey(newInterval);
        if (floorKey != null) {
            int[] floor = intervals.floor(newInterval);
            if (floor[1] >= start - 1) {
                // Merge with floor
                start = Math.min(start, floor[0]);
                end = Math.max(end, floor[1]);
                intervals.remove(floor);
            }
        }

        // Check for intervals that start after or adjacent
        Integer ceilingKey = intervals.ceilingKey(newInterval);
        while (ceilingKey != null) {
            int[] ceiling = intervals.ceiling(newInterval);
            if (ceiling[0] <= end + 1) {
                end = Math.max(end, ceiling[1]);
                intervals.remove(ceiling);
                ceilingKey = intervals.ceilingKey(newInterval);
            } else {
                break;
            }
        }

        intervals.add(new int[]{start, end});
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();

        boolean[] painted = new boolean[N];

        for (int i = 0; i < M; i++) {
            int a = sc.nextInt();
            int L = sc.nextInt();
            for (int j = 0; j < L; j++) {
                painted[(a + j) % N] = true;
            }
        }

        // Find contiguous painted segments on circular array
        List<Integer> lengths = new ArrayList<>();

        // Check if all painted
        boolean allPainted = true;
        for (boolean b : painted) if (!b) { allPainted = false; break; }

        if (allPainted) {
            lengths.add(N);
        } else {
            // Find a starting point that is not painted
            int start = -1;
            for (int i = 0; i < N; i++) {
                if (!painted[i]) { start = i; break; }
            }

            // Traverse from start, find segments
            int i = 0;
            while (i < N) {
                int pos = (start + i) % N;
                if (painted[pos]) {
                    int len = 0;
                    while (i < N && painted[(start + i) % N]) {
                        len++;
                        i++;
                    }
                    lengths.add(len);
                } else {
                    i++;
                }
            }
        }

        // Sort descending
        lengths.sort(Collections.reverseOrder());

        // Count occurrences
        // Output: length and count
        if (lengths.isEmpty()) {
            System.out.println("No painted sections");
            return;
        }

        // Group by length
        Map<Integer, Integer> countMap = new LinkedHashMap<>();
        for (int len : lengths) {
            countMap.merge(len, 1, Integer::sum);
        }

        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Integer, Integer> e : countMap.entrySet()) {
            sb.append(e.getKey()).append(" x ").append(e.getValue()).append("\n");
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

/*
Assumed input format:
N M
a1 L1
a2 L2
...
aM LM

Wall positions are on a circle [0, N).
Each child paints counter-clockwise from a to (a + L) mod N.
We treat this as painting L consecutive unit segments starting at a.
Intervals may overlap and should be merged.
Output:
For each distinct painted-section length in descending order:
length count

If nothing is painted, output nothing.

This solves the standard circular-interval union problem by:
1) Converting each paint action into one or two intervals on [0, N).
2) Merging intervals on the line.
3) If the first merged interval starts at 0 and the last ends at N, merge them across the circle.
4) Count resulting arc lengths and print grouped by length descending.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Interval {
        long l, r; // [l, r)
        Interval(long l, long r) {
            this.l = l;
            this.r = r;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        long N;
        int M;
        try {
            N = fs.nextLong();
            M = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        List<Interval> intervals = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            long a = fs.nextLong();
            long L = fs.nextLong();

            if (N == 0) continue;

            if (L <= 0) continue;

            // Painting at least full circle => everything painted
            if (L >= N) {
                intervals.clear();
                intervals.add(new Interval(0, N));
                // Still need to consume remaining input already handled by loop
                // Mark as full and skip further processing
                for (int j = i + 1; j < M; j++) {
                    fs.nextLong();
                    fs.nextLong();
                }
                outputFullCircle(N);
                return;
            }

            long end = a + L;
            if (end < N) {
                intervals.add(new Interval(a, end));
            } else {
                intervals.add(new Interval(a, N));
                intervals.add(new Interval(0, end % N));
            }
        }

        if (intervals.isEmpty()) {
            return;
        }

        intervals.sort((x, y) -> {
            if (x.l != y.l) return Long.compare(x.l, y.l);
            return Long.compare(x.r, y.r);
        });

        List<Interval> merged = new ArrayList<>();
        long cl = intervals.get(0).l;
        long cr = intervals.get(0).r;

        for (int i = 1; i < intervals.size(); i++) {
            Interval in = intervals.get(i);
            if (in.l <= cr) {
                cr = Math.max(cr, in.r);
            } else {
                merged.add(new Interval(cl, cr));
                cl = in.l;
                cr = in.r;
            }
        }
        merged.add(new Interval(cl, cr));

        // Merge across circular boundary if needed
        if (merged.size() >= 2) {
            Interval first = merged.get(0);
            Interval last = merged.get(merged.size() - 1);
            if (first.l == 0 && last.r == N) {
                long newL = last.l;
                long newR = first.r;
                List<Interval> circularMerged = new ArrayList<>();
                circularMerged.add(new Interval(newL, newR)); // wrapped interval
                for (int i = 1; i < merged.size() - 1; i++) {
                    circularMerged.add(merged.get(i));
                }
                merged = circularMerged;
            }
        }

        Map<Long, Long> freq = new TreeMap<>(Collections.reverseOrder());

        for (Interval in : merged) {
            long len;
            if (in.l <= in.r) {
                len = in.r - in.l;
            } else {
                len = (N - in.l) + in.r;
            }
            if (len > 0) {
                freq.put(len, freq.getOrDefault(len, 0L) + 1);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Long, Long> e : freq.entrySet()) {
            sb.append(e.getKey()).append(' ').append(e.getValue()).append('\n');
        }
        System.out.print(sb.toString());
    }

    static void outputFullCircle(long N) {
        if (N <= 0) return;
        System.out.println(N + " 1");
    }
}
